function estimateTokens(text){
  if(!text) return 0;
  var s=String(text);
  var cjk=(s.match(/[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]/g)||[]).length;
  var rest=s.length-cjk;
  return Math.ceil(cjk*1.0 + rest/4);
}
function planChunks(totalTokens, chunkSize, overlap){
  totalTokens=Math.max(0, Math.floor(totalTokens||0));
  chunkSize=Math.max(1, Math.floor(chunkSize||0));
  overlap=Math.max(0, Math.floor(overlap||0));
  if(overlap>=chunkSize) return {error:'overlap 必须小于 chunkSize', count:0, stride:0, redundancy:0};
  var stride=chunkSize-overlap;
  if(totalTokens===0) return {error:null, count:0, stride:stride, redundancy:0, lastChunk:0};
  var count = totalTokens<=chunkSize ? 1 : Math.ceil((totalTokens-overlap)/stride);
  var covered = count*chunkSize - (count-1)*overlap;
  var stored = count*chunkSize;
  var redundancy = totalTokens>0 ? Math.round(((stored/totalTokens)-1)*1000)/10 : 0;
  var lastChunk = totalTokens<=chunkSize ? totalTokens : totalTokens-(count-1)*stride;
  return {error:null, count:count, stride:stride, covered:covered, stored:stored, redundancy:redundancy, lastChunk:lastChunk};
}
function contextBudget(chunkSize, topK, promptTokens, maxContext, reserveOutput){
  chunkSize=Math.max(0,Math.floor(chunkSize||0));
  topK=Math.max(0,Math.floor(topK||0));
  promptTokens=Math.max(0,Math.floor(promptTokens||0));
  maxContext=Math.max(1,Math.floor(maxContext||0));
  reserveOutput=Math.max(0,Math.floor(reserveOutput||0));
  var retrieved=chunkSize*topK;
  var used=retrieved+promptTokens;
  var available=maxContext-reserveOutput;
  var fits=used<=available;
  var maxTopK = chunkSize>0 ? Math.max(0, Math.floor((available-promptTokens)/chunkSize)) : 0;
  return {retrieved:retrieved, used:used, available:available, fits:fits,
          headroom:available-used, utilization:Math.round((used/available)*1000)/10, maxTopK:maxTopK};
}
function embedCost(chunkCount, chunkSize, pricePerMillion){
  var tokens=Math.max(0,chunkCount||0)*Math.max(0,chunkSize||0);
  var usd=(tokens/1000000)*(pricePerMillion||0);
  return {tokens:tokens, usd:Math.round(usd*1000000)/1000000, cny:Math.round(usd*7.2*1000000)/1000000};
}
function splitText(text, chunkChars, overlapChars){
  var s=String(text||'');
  chunkChars=Math.max(1,Math.floor(chunkChars||0));
  overlapChars=Math.max(0,Math.floor(overlapChars||0));
  if(overlapChars>=chunkChars) overlapChars=chunkChars-1;
  var out=[], stride=chunkChars-overlapChars, i=0;
  if(s.length===0) return out;
  while(i<s.length){
    out.push(s.slice(i, i+chunkChars));
    if(i+chunkChars>=s.length) break;
    i+=stride;
  }
  return out;
}
function recallHint(topK, chunkSize){
  if(topK<=0) return '未检索任何片段，模型只能靠参数化知识回答';
  if(chunkSize<128) return '片段过小，语义可能被截断，建议 256-512';
  if(chunkSize>1500) return '片段过大，噪声高且浪费上下文，建议 512-1024';
  if(topK<3) return 'topK 偏低，召回可能不足，建议 3-8';
  if(topK>12) return 'topK 偏高，噪声上升且成本增加，建议 3-8';
  return '参数处于常见推荐区间';
}
